// Generated by Cypress Author on 2026-10-11.
import ConnectSpotify from './ConnectSpotify.tsx';

const card = '[data-cy="connect-spotify"]';

describe('<ConnectSpotify />', () => {
  it('clicking "Connect Spotify" → sends the user to Spotify', () => {
    const onConnect = cy.stub().as('onConnect').resolves();
    cy.mount(<ConnectSpotify onConnect={onConnect} />);

    cy.contains(`${card} h2`, 'Connect your Spotify account').should('be.visible');
    cy.contains(`${card} button`, 'Connect Spotify').click();

    cy.get('@onConnect').should('have.been.calledOnce');
  });

  it('connecting fails → explains the problem so the user can retry', () => {
    cy.mount(<ConnectSpotify onConnect={cy.stub().rejects(new Error('network'))} />);

    cy.contains(`${card} button`, 'Connect Spotify').click();

    cy.get(card).should('contain.text', "We couldn't reach Spotify. Please try again.");
    cy.contains(`${card} button`, 'Connect Spotify').should('be.enabled');
  });

  it('matches the visual baseline', () => {
    cy.viewport(800, 300);
    cy.mount(<ConnectSpotify onConnect={cy.stub().resolves()} />);

    cy.contains('Connect your Spotify account').should('be.visible');
    cy.get(card).matchImage();
  });

  // Below MUI's `sm` breakpoint (600px) the icon, text and button stack vertically.
  it('matches the visual baseline on a phone', () => {
    cy.viewport(400, 500);
    cy.mount(<ConnectSpotify onConnect={cy.stub().resolves()} />);

    cy.contains('Connect your Spotify account').should('be.visible');
    cy.get(card).matchImage();
  });
});
